"use client";

import { useMemo, useState } from "react";
import styles from "./page.module.css";

const sneakers = [
    { id: 1, name: "Air Max 95", brand: "Nike", colorway: "Neon", price: 1299, status: "Na coleção", tag: "Ícone", tone: "lime", image: "https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=900&q=85" },
    { id: 2, name: "Gel-NYC", brand: "ASICS", colorway: "Cream / Oyster", price: 1099, status: "Na lista", tag: "Em alta", tone: "blue", image: "https://images.unsplash.com/photo-1552346154-21d32810aba3?auto=format&fit=crop&w=900&q=85" },
    { id: 3, name: "9060", brand: "New Balance", colorway: "Sea Salt", price: 1199, status: "Na coleção", tag: "Essencial", tone: "sand", image: "https://images.unsplash.com/photo-1539185441755-769473a23570?auto=format&fit=crop&w=900&q=85" },
    { id: 4, name: "Dunk Low", brand: "Nike", colorway: "Vintage Green", price: 899, status: "Procurando", tag: "Novo", tone: "green", image: "https://images.unsplash.com/photo-1608231387042-66d1773070a5?auto=format&fit=crop&w=900&q=85" },
    { id: 5, name: "Campus 00s", brand: "Adidas", colorway: "Grey White", price: 749, status: "Na coleção", tag: "Street", tone: "grey", image: "https://images.unsplash.com/photo-1525966222134-fcfa99b8ae77?auto=format&fit=crop&w=900&q=85" },
    { id: 6, name: "Air Jordan 1 High", brand: "Jordan", colorway: "Chicago Lost & Found", price: 1899, status: "Na lista", tag: "Grail", tone: "red", image: "https://images.unsplash.com/photo-1552346154-21d32810aba3?auto=format&fit=crop&w=900&q=85" }];
const money = v => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 }).format(v);
export default function Home() {
    const [query, setQuery] = useState(""); const [brand, setBrand] = useState("Todos"); const [filter, setFilter] = useState("Todos os pares"); const [saved, setSaved] = useState([]);
    const visible = useMemo(() => sneakers.filter(s => `${s.name} ${s.brand} ${s.colorway}`.toLowerCase().includes(query.toLowerCase()) && (brand === "Todos" || s.brand === brand) && (filter === "Todos os pares" || (filter === "Na coleção" ? s.status === "Na coleção" : s.status !== "Na coleção"))), [query, brand, filter]);
    return <main className={styles.site}>
        <div className={styles.topline}><span>CURADORIA INDEPENDENTE · DESDE 2024</span><span>ENTRE NO UNIVERSO FRED <b>↗</b></span></div>
        <header className={styles.header}><a href="#" className={styles.wordmark}>FRED<sup>®</sup><small>SNEAKERS</small></a><nav className={styles.nav}><a className={styles.active} href="#catalogo">Catálogo</a><a href="#sobre">Sobre a Fred</a><a href="#colecao">Minha coleção <sup>{saved.length}</sup></a></nav><a className={styles.addButton} href="#catalogo">Explorar pares <span>↗</span></a></header>
        <section className={styles.hero} id="sobre"><div className={styles.heroCopy}><div className={styles.eyebrow}><i /> CULTURA QUE SE CALÇA</div><h1>Seu próximo<br />par favorito<br /><em>está aqui.</em></h1><p>Um acervo feito para quem sabe que tênis nunca é só tênis. Descubra modelos, colorways e histórias.</p><a href="#catalogo" className={styles.heroLink}>EXPLORE O CATÁLOGO <span>↓</span></a></div><div className={styles.heroVisual}><div className={styles.heroImage} /><span className={styles.heroStamp}>F<br />S</span><div className={styles.heroCaption}><span>01 / 06</span><span>THE DAILY ROTATION</span></div><span className={styles.verticalText}>FRED SNEAKERS — CURATED FOR THE CULTURE</span></div><div className={styles.heroIndex}>01<br />—<br />06</div></section>
        <div className={styles.ticker}><div>FIND YOUR FREQUENCY <i>✳</i> WALK YOUR WAY <i>✳</i> BUILT FOR THE ROTATION <i>✳</i> FIND YOUR FREQUENCY <i>✳</i> WALK YOUR WAY <i>✳</i></div></div>
        <section className={styles.catalog} id="catalogo"><div className={styles.sectionHeading}><div><div className={styles.eyebrow}>A SELEÇÃO FRED <span>— 2025 / 26</span></div><h2>O <em>catálogo.</em></h2></div><p>Modelos que falam por si.<br />Escolha seu próximo capítulo.</p></div>
            <div className={styles.toolbar}><div className={styles.filterTabs}>{["Todos os pares", "Na coleção", "Na lista"].map(x => <button key={x} className={filter === x ? styles.selectedTab : ""} onClick={() => setFilter(x)}>{x}<span>{x === "Todos os pares" ? "06" : x === "Na coleção" ? "03" : "03"}</span></button>)}</div><div className={styles.controls}><label className={styles.search}><span>⌕</span><input aria-label="Buscar tênis" placeholder="Buscar modelo..." value={query} onChange={e => setQuery(e.target.value)} /></label><select aria-label="Filtrar por marca" value={brand} onChange={e => setBrand(e.target.value)}>{["Todos", "Nike", "ASICS", "New Balance", "Adidas", "Jordan"].map(x => <option key={x}>{x}</option>)}</select><button className={styles.sort} aria-label="Ordenar">↕</button></div></div>
            <div className={styles.grid}>{visible.map((s, i) => <article className={styles.card} key={s.id}><div className={`${styles.productImage} ${styles[s.tone]}`}><img src={s.image} alt={`${s.brand} ${s.name} ${s.colorway}`} /><span className={styles.badge}>{s.tag}</span><button className={`${styles.heart} ${saved.includes(s.id) ? styles.hearted : ""}`} aria-label="Favoritar" onClick={() => setSaved(a => a.includes(s.id) ? a.filter(n => n !== s.id) : [...a, s.id])}>{saved.includes(s.id) ? "♥" : "♡"}</button><span className={styles.cardNumber}>0{i + 1}</span></div><div className={styles.cardInfo}><div><span className={styles.brand}>{s.brand}</span><h3>{s.name}</h3><p>{s.colorway}</p></div><strong>{money(s.price)}</strong></div><div className={styles.cardBottom}><span className={s.status === "Na coleção" ? styles.owned : styles.wanted}><i /> {s.status}</span><button aria-label={`Ver ${s.name}`}>↗</button></div></article>)}</div>
            {visible.length === 0 && <p className={styles.empty}>Nenhum par encontrado. Tente outra busca.</p>}<div className={styles.catalogFooter}><span>MOSTRANDO {String(visible.length).padStart(2, "0")} DE 06 PARES</span><button onClick={() => { setQuery(""); setBrand("Todos"); setFilter("Todos os pares") }}>VER TODOS OS PARES <b>↗</b></button></div></section>
        <footer className={styles.footer}><a href="#" className={styles.wordmark}>FRED<sup>®</sup><small>SNEAKERS</small></a><span>FEITO PARA QUEM VIVE A CULTURA.</span><span>© FRED SNEAKERS 2025</span></footer></main>
}
